import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def find_blocks(g):
    H,W=len(g),len(g[0]); blocks=[]
    for r in range(H-2):
        for c in range(W-2):
            v=g[r][c]
            if v and all(g[r+i][c+j]==v for i in range(3) for j in range(3)):
                blocks.append((v,r,c))
    # keep maximal: drop blocks contained in others (same color overlapping)
    out=[]
    for v,r,c in blocks:
        if not any(v2==v and r2<=r<=r2+2 and c2<=c<=c2+2 and (r2,c2)!=(r,c) for v2,r2,c2 in blocks):
            out.append((v,r,c))
    return out

def f(g):
    H,W=len(g),len(g[0])
    o=[row[:] for row in g]
    blocks=find_blocks(g)
    hlines=[]; vlines=[]
    for v,r,c in blocks:
        for i in range(3):
            for j in range(3):
                o[r+i][c+j]=v
    for v,r,c in blocks:
        hr=r+1; hc=c+1
        hlines.append((hr,v)); vlines.append((hc,v))
        for j in range(W): o[hr][j]=v
        for i in range(H): o[i][hc]=v
    for hr,va in hlines:
        for hc,vb in vlines:
            if va!=vb: o[hr][hc]=0
    return o
print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
print(json.dumps(f(G['Test input'])))

